#pragma once
#include "PluginProcessor.h"
#include <juce_dsp/juce_dsp.h>
// Parameter diagrams use normalized values. Filter curves are illustrative,
// not transfer-function measurements; the output trace is actual mixed audio.
struct ParameterGraphic:juce::Component {
 enum Kind{Envelope,Lfo,Filter,Levels,Scope,Delay,Reverb,Equalizer,Routing,Distortion,ModDelay,Spectrum};
 enum Source{Native,Sample,Rack};Source source;SynthMavenProcessor&p;Kind kind;int layer,base;int cutoff=-1,resonance=-1,drag=-1;juce::dsp::FFT fft{9};std::array<float,1024>spectrum{};
 ParameterGraphic(SynthMavenProcessor&proc,Kind k,int b=1,Source src=Native):source(src),p(proc),kind(k),layer(proc.selectedLayer.load()),base(b){
  for(int i=118;i<126;i++){auto name=p.parameterLabel(i,layer);if(name=="CUT")cutoff=i;if(name=="RES")resonance=i;}
  if(source==Sample){cutoff=10;resonance=11;}setMouseCursor(juce::MouseCursor::CrosshairCursor);
 }
 juce::String id(int i)const{return source==Sample?p.sampleId(layer,p.sampleKeys[i]):source==Rack?p.layerId(layer,OscillatorRack::keys[i]):p.parameterId(i,layer);}
 float value(int i)const{auto*v=p.parameters.getRawParameterValue(id(i));return v?v->load():0;}
 void write(int i,float v){if(auto*param=p.parameters.getParameter(id(i))){param->setValueNotifyingHost(juce::jlimit(0.f,1.f,v));}}
 juce::Rectangle<float>plot()const{return getLocalBounds().toFloat().reduced(16,28).withTrimmedBottom(4);}
 juce::Point<float>point(float x,float y)const{auto r=plot();return {r.getX()+x*r.getWidth(),r.getBottom()-y*r.getHeight()};}
 std::array<juce::Point<float>,3>handles()const{float a=value(base),d=value(base+1),s=value(base+2),r=value(base+3);return {point(.04f+.25f*a,1),point(.09f+.25f*a+.2f*d,s),point(.75f+.24f*r,0)};}
 void paint(juce::Graphics&g)override{
  using namespace juce;auto bounds=getLocalBounds().toFloat();g.setColour(Colour(0xff101923));g.fillRoundedRectangle(bounds,6);auto r=plot();g.setColour(Colour(0xff243442));for(int i=0;i<=8;i++)g.drawVerticalLine(roundToInt(r.getX()+r.getWidth()*i/8),r.getY(),r.getBottom());for(int i=0;i<=4;i++)g.drawHorizontalLine(roundToInt(r.getY()+r.getHeight()*i/4),r.getX(),r.getRight());
  String title=kind==Envelope?"ENVELOPE / NORMALIZED SHAPE":kind==Lfo?"LFO / WAVEFORM PREVIEW":kind==Filter?"FILTER / ILLUSTRATIVE RESPONSE":kind==Levels?"EFFECT SENDS":kind==Delay?"DELAY / ECHO PREVIEW":kind==Reverb?"REVERB / DECAY PREVIEW":kind==Equalizer?"EQ / ILLUSTRATIVE RESPONSE":kind==Routing?"MODULATION / ACTIVE CONNECTIONS":kind==Distortion?"DISTORTION / TRANSFER PREVIEW":kind==ModDelay?"MODULATED DELAY / PREVIEW":kind==Spectrum?"LIVE SPECTRUM / MIXED MONO OUTPUT":"LIVE OUTPUT / ALL LAYERS";
  g.setColour(Colour(0xff8394a7));g.setFont(10);g.drawText(title,12,5,getWidth()-24,16,Justification::centredLeft);Path path;
  if(kind==Envelope){auto h=handles();path.startNewSubPath(point(0,0));path.lineTo(h[0]);path.quadraticTo(h[0].x,h[1].y,h[1].x,h[1].y);path.lineTo(point(.72f,value(base+2)));path.lineTo(h[2]);for(int i=0;i<3;i++){g.setColour(Colour(0xff56e5c7));g.fillEllipse(h[i].x-4,h[i].y-4,8,8);}g.setColour(Colour(0xff8394a7));String caption="Attack  /  Decay  /  Sustain  /  Release    /    Drag handles";g.drawText(caption,12,getHeight()-22,getWidth()-24,16,Justification::centredLeft);g.setFont(9);g.drawText("A",(int)h[0].x+7,(int)r.getY(),18,14,Justification::left);g.drawText("D / S",(int)h[1].x+7,juce::jlimit((int)r.getY()+2,(int)r.getBottom()-16,(int)h[1].y-18),42,14,Justification::left);g.drawText("R",(int)h[2].x-20,(int)h[2].y-20,18,14,Justification::left);}
  else if(kind==Lfo){auto info=sm_parameter_info(p.selectedEngine(layer),base+1);int choice=info.minimum+roundToInt(value(base+1)*(info.maximum-info.minimum));String wave=source==Native?sm_parameter_choice(p.selectedEngine(layer),base+1,choice):"SIN";float cycles=1+value(base)*3;for(int n=0;n<=400;n++){float x=n/400.f,t=std::fmod(x*cycles,1.f),y=std::sin(t*MathConstants<float>::twoPi);if(wave.containsIgnoreCase("TRI"))y=1-4*std::abs(t-.5f);else if(wave.containsIgnoreCase("SQR")||wave.containsIgnoreCase("SQU"))y=t<.5f?1:-1;else if(wave.containsIgnoreCase("SAW"))y=t*2-1;else if(wave.containsIgnoreCase("RND")||wave.containsIgnoreCase("S&H"))y=std::sin(std::floor(x*cycles*8)*73.23f);auto q=point(x,.5f+y*.44f);if(n==0)path.startNewSubPath(q);else path.lineTo(q);}g.setColour(Colour(0xff8394a7));g.drawText(wave+" / rate "+(source==Native?p.parameterText(base,value(base),layer):String(.05f+value(base)*value(base)*20,2)+" Hz"),12,getHeight()-22,getWidth()-24,16,Justification::centredLeft);}
  else if(kind==Filter){if(cutoff<0){g.setColour(Colour(0xff8394a7));g.drawText("This engine has no exposed cutoff / resonance pair",r,Justification::centred);return;}String model=source==Native?p.parameterText(46,value(46),layer):"SVF";float c=value(cutoff),res=resonance<0?0:value(resonance);for(int n=0;n<=400;n++){float x=n/400.f,y=.78f/(1+std::pow(10.f,(x-c)*6))+.18f*res*std::exp(-std::pow((x-c)*20,2));if(model=="HP")y=.78f-y;else if(model=="BP")y=.8f*std::exp(-std::pow((x-c)*(5+res*12),2));else if(model.containsIgnoreCase("NOT"))y=.8f-.75f*std::exp(-std::pow((x-c)*(5+res*12),2));auto q=point(x,juce::jlimit(0.f,1.f,y));if(n==0)path.startNewSubPath(q);else path.lineTo(q);}g.setColour(Colour(0xff8394a7));g.drawText("Drag: cutoff left/right, resonance up/down / low -> high frequency",12,getHeight()-22,getWidth()-24,16,Justification::centredLeft);}
  else if(kind==Levels){const char*names[]={"CHORUS","DELAY","REVERB"};for(int i=0;i<3;i++){auto bar=r.withX(r.getX()+i*r.getWidth()/3+8).withWidth(r.getWidth()/3-16);g.setColour(Colour(0xff263b42));g.fillRect(bar);g.setColour(Colour(0xff56e5c7));g.fillRect(bar.removeFromBottom(bar.getHeight()*value(34+i)));g.setColour(Colours::white);g.drawText(names[i],r.getX()+i*r.getWidth()/3,r.getY(),r.getWidth()/3,18,Justification::centred);}return;}
  else if(kind==Delay){static const float beats[]={1,.5f,.25f,.125f,1.f/3,1.f/6,.75f,.375f};float send=value(35),feedback=p.sampleEnabled(layer)?.3f:value(131)*(120.f/127);float spacing=p.sampleEnabled(layer)?.125f:30.f/(40+value(126)*200)*beats[juce::jlimit(0,7,juce::roundToInt(value(130)*7))];for(int echo=0;echo<9;echo++){float x=.03f+echo*spacing;if(x>1)break;float amp=echo==0?1:send*std::pow(feedback,echo-1);auto q=point(x,.06f+.86f*amp);g.setColour(echo==0?Colour(0xff8394a7):Colour(0xff56e5c7));g.drawLine(q.x,r.getBottom(),q.x,q.y,4);g.drawText(echo==0?"DRY":String(echo),int(q.x)+5,int(q.y),35,15,Justification::left);}g.setColour(Colour(0xff8394a7));g.drawText(p.sampleEnabled(layer)?"Sampler: fixed 250 ms / fixed feedback  /  drag to edit send":"0-2 s at internal tempo / amplitudes illustrative  /  drag: time / send",12,getHeight()-22,getWidth()-24,16,Justification::centredLeft);return;}
  else if(kind==Reverb){float size=p.sampleEnabled(layer)?.65f:value(134),damp=p.sampleEnabled(layer)?.5f:value(135),send=value(36);for(int n=0;n<=400;n++){float x=n/400.f,y=send*.88f*std::exp(-x*(2+9*(1-size)));auto q=point(x,y);if(n==0)path.startNewSubPath(q);else path.lineTo(q);if(n%8==0){g.setColour(Colour(0xffaa87ed).withAlpha(.45f));float high=y*std::exp(-x*damp*8);g.drawVerticalLine(int(q.x),q.y,r.getBottom()-high*r.getHeight());}}g.setColour(Colour(0xff8394a7));g.drawText(p.sampleEnabled(layer)?"Sampler: fixed size/damping  /  drag to edit send":"Illustrative decay / damping  /  drag: size left/right, send up/down",12,getHeight()-22,getWidth()-24,16,Justification::centredLeft);}
  else if(kind==Equalizer){for(int n=0;n<=400;n++){float x=n/400.f,low=(value(151)-.5f),mid=(value(150)-.5f),high=(value(152)-.5f);float y=.5f+.55f*(low/(1+std::exp((x-.22f)*20))+mid*std::exp(-std::pow((x-.5f)*6,2))+high/(1+std::exp((.78f-x)*20)));auto q=point(x,juce::jlimit(0.f,1.f,y));if(n==0)path.startNewSubPath(q);else path.lineTo(q);}g.setColour(Colour(0xff8394a7));g.drawText("LOW                         MID                         HIGH / illustrative",12,getHeight()-22,getWidth()-24,16,Justification::centredLeft);}
  else if(kind==Routing){int active=0;for(int slot=0;slot<6;slot++){int i=base+slot*3;if(value(i)<=0||value(i+1)<=0)continue;float y=r.getY()+(active+.5f)*r.getHeight()/6;g.setColour(Colour(0xff8394a7));g.drawText(p.parameterText(i,value(i),layer),r.getX(),int(y)-8,int(r.getWidth()*.3f),18,Justification::left);g.drawText(p.parameterText(i+1,value(i+1),layer),int(r.getX()+r.getWidth()*.72f),int(y)-8,int(r.getWidth()*.28f),18,Justification::right);g.setColour(Colour(0xff56e5c7));g.drawLine(r.getX()+r.getWidth()*.3f,y,r.getX()+r.getWidth()*.7f,y,1+3*std::abs(value(i+2)-.5f));active++;}if(active==0){g.setColour(Colour(0xff8394a7));g.drawText("Choose source -> destination in the slots below to create connections",r,Justification::centred);}return;}
  else if(kind==Distortion){float drive=1+value(33)*12;for(int n=0;n<=400;n++){float x=n/400.f,y=.5f+.46f*std::tanh((x*2-1)*drive)/std::tanh(drive);auto q=point(x,y);if(n==0)path.startNewSubPath(q);else path.lineTo(q);}g.setColour(Colour(0xff8394a7));g.drawText("Illustrative input -> output saturation  /  drag to edit distortion",12,getHeight()-22,getWidth()-24,16,Justification::centredLeft);}
  else if(kind==ModDelay){float rate=value(base+1),depth=value(base+2);for(int channel=0;channel<2;channel++){Path trace;for(int n=0;n<=300;n++){float x=n/300.f,y=.5f+std::sin(x*(1+rate*4)*MathConstants<float>::twoPi+channel*1.4f)*depth*.42f;auto q=point(x,y);if(n==0)trace.startNewSubPath(q);else trace.lineTo(q);}g.setColour(channel==0?Colour(0xff56e5c7):Colour(0xffaa87ed));g.strokePath(trace,PathStrokeType(1.5f));}g.setColour(Colour(0xff8394a7));g.drawText("Left / right delay modulation  /  drag horizontally for rate, vertically for depth",12,getHeight()-22,getWidth()-24,16,Justification::centredLeft);return;}
  else if(kind==Spectrum){spectrum.fill(0);unsigned head=p.scopeWrite.load();for(int n=0;n<512;n++)spectrum[n]=p.scope[(head+n)%512].load()*(.5f-.5f*std::cos(juce::MathConstants<float>::twoPi*n/511));fft.performFrequencyOnlyForwardTransform(spectrum.data());float sr=(float)p.getSampleRate();if(sr<8000)sr=44100;for(int n=0;n<=400;n++){float x=n/400.f,hz=20*std::pow((sr*.5f)/20,x),bin=juce::jlimit(0.f,255.f,hz/sr*512);int lo=(int)bin;float magnitude=(spectrum[lo]*(1-(bin-lo))+spectrum[juce::jmin(256,lo+1)]*(bin-lo))/128;float y=juce::jlimit(0.f,1.f,(juce::Decibels::gainToDecibels(magnitude,-90.f)+90)/90);auto q=point(x,y);if(n==0)path.startNewSubPath(q);else path.lineTo(q);}g.setColour(Colour(0xff8394a7));g.drawText("20 Hz                       log frequency                       Nyquist / -90 to 0 dBFS",12,getHeight()-22,getWidth()-24,16,Justification::centredLeft);}
  else {unsigned head=p.scopeWrite.load();for(unsigned n=0;n<512;n++){auto q=point(n/511.f,.5f+juce::jlimit(-1.f,1.f,p.scope[(head+n)%512].load())*.46f);if(n==0)path.startNewSubPath(q);else path.lineTo(q);}}
  g.setColour(Colour(0xff56e5c7));g.strokePath(path,PathStrokeType(2));
 }
 void mouseDown(const juce::MouseEvent&e)override{drag=-1;if(e.mods.isPopupMenu())return;if(kind==Envelope){auto h=handles();float distance=30;for(int i=0;i<3;i++){float d=h[i].getDistanceFrom(e.position);if(d<distance){distance=d;drag=i;}}}else if(kind==Filter&&cutoff>=0)drag=0;else if(kind==Equalizer)drag=juce::jlimit(0,2,int((e.x-plot().getX())/(plot().getWidth()/3)));else if(kind==Delay||kind==Reverb||kind==Distortion||kind==ModDelay||kind==Lfo)drag=0;else if(kind==Levels)drag=juce::jlimit(0,2,int((e.x-plot().getX())/(plot().getWidth()/3)));for(int i:editing())if(auto*q=p.parameters.getParameter(id(i)))q->beginChangeGesture();mouseDrag(e);}
 std::vector<int>editing()const{if(drag<0)return {};if(kind==Envelope)return drag==0?std::vector<int>{base}:drag==1?std::vector<int>{base+1,base+2}:std::vector<int>{base+3};if(kind==Filter)return resonance>=0?std::vector<int>{cutoff,resonance}:std::vector<int>{cutoff};if(kind==Levels)return {34+drag};if(kind==Equalizer)return {drag==0?151:drag==1?150:152};if(kind==Lfo)return {base};if(kind==Delay)return p.sampleEnabled(layer)?std::vector<int>{35}:std::vector<int>{35,130};if(kind==Reverb)return p.sampleEnabled(layer)?std::vector<int>{36}:std::vector<int>{36,134};if(kind==Distortion)return {33};if(kind==ModDelay)return {base+1,base+2};return {};}
 void mouseDrag(const juce::MouseEvent&e)override{if(drag<0)return;auto r=plot();float x=(e.x-r.getX())/r.getWidth(),y=1-(e.y-r.getY())/r.getHeight();if(kind==Envelope){if(drag==0)write(base,(x-.04f)/.25f);if(drag==1){write(base+1,(x-.09f-.25f*value(base))/.2f);write(base+2,y);}if(drag==2)write(base+3,(x-.75f)/.24f);}else if(kind==Filter){write(cutoff,x);if(resonance>=0)write(resonance,y);}else if(kind==Levels)write(34+drag,y);else if(kind==Equalizer)write(drag==0?151:drag==1?150:152,.5f+(y-.5f)/.55f);else if(kind==Lfo)write(base,x);else if(kind==Delay){write(35,y);if(!p.sampleEnabled(layer))write(130,x);}else if(kind==Reverb){write(36,y);if(!p.sampleEnabled(layer))write(134,x);}else if(kind==Distortion)write(33,x);else if(kind==ModDelay){write(base+1,x);write(base+2,y);}repaint();}
 void mouseUp(const juce::MouseEvent&)override{for(int i:editing())if(auto*q=p.parameters.getParameter(id(i)))q->endChangeGesture();drag=-1;}
};
